<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRelyingPartyVO;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\RelyingPartyRef;

trait PlatformIdentityRelyingPartyAccessor
{
    private ?PlatformIdentityRelyingPartyVO $_relyingParty = null;
    public function getRelyingParty(): ?RelyingPartyRef
    {
        return $this->_relyingParty?->value();
    }
    public function relyingParty(): ?PlatformIdentityRelyingPartyVO
    {
        return $this->_relyingParty;
    }
    public function isRelyingPartyChanged(?self $original = null): bool
    {
        return null !== $this->_relyingParty && !$this->_relyingParty->equals($original?->_relyingParty);
    }
    public function withRelyingParty(PlatformIdentityRelyingPartyVO|RelyingPartyRef|null $relyingParty): self
    {
        $copy = clone $this;
        $copy->_relyingParty = PlatformIdentityRelyingPartyVO::from($relyingParty);
        return $copy;
    }
}
